procedure PrintCycle(u, v);
var x, y, low, high : vertex;
begin
  x := u; y := v;
  while (x <> v) and (y <> u) do
  begin x := P[x]; y := P[y] end;
  if x = v then begin low := u; high := v end
           else begin low := v; high := u end;
  { low is the descendant, high the ancestor }
  x := low;
  while x <> high do
  begin write(x); x := P[x] end;
  write(high); writeln(low)   { edge (high, low) closes the cycle }
end;
